"""The category_agent graph state — what flows between its top-level nodes.

A LangGraph ``TypedDict`` (``total=False``, so each node returns only the keys it
sets). Linear flow: describe the category, then write it. ``result`` is what
``run()`` returns.
"""
from __future__ import annotations

from typing import TypedDict


class CategoryState(TypedDict, total=False):
    # inputs
    topic: str             # free-text field/topic the user wants to create
    category_slug: str     # filename-safe slug derived from ``topic``

    # generated by the LLM
    name: str              # human-readable category name (the topic, cleaned up)
    description: str       # short technical description of the category
    seminal_papers: list[dict]  # foundational/seminal papers for the category

    # output
    result: dict
